HUB={h[0]:h for h in AR.HUBS}; ART={a[0]:a for a in ARTS}
wb=load_workbook(os.path.join(ROOT,'out/_partial.xlsx'))
HDR=Font(bold=True,color='FFFFFF',size=10); HFILL=PatternFill('solid',fgColor='2F5597')
WRAP=Alignment(vertical='top',wrap_text=True); THIN=Border(*[Side(style='thin',color='D9D9D9')]*4)
def sheet(name,headers,rows,widths=None):
    ws=wb.create_sheet(name[:31]); ws.append(headers)
    for c in ws[1]:
        c.font=HDR; c.fill=HFILL; c.alignment=Alignment(vertical='center',wrap_text=True)
    for r in rows: ws.append(list(r))
    ws.freeze_panes='A2'; ws.row_dimensions[1].height=32
    ws.auto_filter.ref=f'A1:{get_column_letter(len(headers))}{max(ws.max_row,1)}'
    for i,h in enumerate(headers,1):
        ws.column_dimensions[get_column_letter(i)].width=(widths[i-1] if widths and i-1<len(widths) else 22)
    for row in ws.iter_rows(min_row=2):
        for c in row: c.alignment=WRAP; c.border=THIN
    return ws

# ---- метрики ----
tot=len(SEM); acc=sum(1 for r in SEM if r['status']=='принято')
exc=sum(1 for r in SEM if r['status']=='исключено'); res=sum(1 for r in SEM if r['status']=='резерв')
