serp_rows=sum(1 for _ in csv.DictReader(open(os.path.join(ROOT,'raw/serp/serp.tsv'),encoding='utf-8'),delimiter='\t'))
pg_ok=sum(1 for p in PAGES if p.get('status')=='ok'); pg_all=len(PAGES)
blocks=sum(len(v) for v in BLOCKS.values())
seas_q=len({r['query'] for r in csv.DictReader(open(os.path.join(ROOT,'raw/seasonality/seasonality.tsv'),encoding='utf-8'),delimiter='\t')})
narrow_n=sum(1 for i,l in enumerate(open(os.path.join(ROOT,'raw/wordstat/narrow.tsv'),encoding='utf-8')) if i>0 and '\t' in l)
alice=list(csv.DictReader(open(os.path.join(ROOT,'raw/serp/alice.tsv'),encoding='utf-8'),delimiter='\t'))
