# ===== 29 Исходные данные =====
raw=[]
i=0
for f in sorted(glob.glob(os.path.join(ROOT,'raw/wordstat/m*.tsv'))):
    src='S01:'+os.path.basename(f).split('_')[0]
    marker=os.path.basename(f).split('_',1)[1].replace('.tsv','')
    for line in open(f,encoding='utf-8'):
        line=line.rstrip('\n')
        if '\t' not in line: continue
        p,v=line.rsplit('\t',1); i+=1
        n=re.sub(r'\s+',' ',re.sub(r'[^\wа-я0-9\s\-]',' ',p.lower().replace('ё','е'))).strip()
        qid=next((r['query_id'] for r in SEM if r['norm']==n),'')
        raw.append((f'R{i:05d}',src,marker,p,v,qid))
sheet('29 Исходные данные',['raw_id','source_id','Маркер','Исходная запись (фраза как отдана Вордстатом)','Значение','query_id при сопоставлении'],
      raw,[12,12,36,60,12,14])

